125	      setConfigText(baseText);
126	    }
127	    // Deliberately runs once: this is a mount-time migration from sessionStorage into React
128	    // state, not a reaction to any prop/state change.
129	    // eslint-disable-next-line react-hooks/exhaustive-deps
130	  }, []);
131	
132	  // Saves the reader's own session on every change (see studioHandoff.js's SESSION_KEY doc
133	  // comment) so navigating away - to read another segment doc, say - and back finds this studio
134	  // exactly as it was left, which is what lets a second "Add to Studio" hand-off accumulate on
135	  // top of the first instead of landing on a fresh pristine starter.
136	  useEffect(() => {
137	    trySessionStorageSet(SESSION_KEY, JSON.stringify({ format, text: configText }));
138	  }, [format, configText]);
139	
140	  // Render the starter config as soon as the module is ready, so a prompt appears on first
141	  // paint without the user having to touch the editor.
142	  useEffect(() => {
143	    if (wasmStatus === 'ready') {
144	      runRender(configText);
145	    }
146	    // configText is intentionally not a dependency: this effect's only job is the one render
147	    // that happens the moment the module becomes ready, not every keystroke after - the
