// windowGeometry is every coordinate the terminal-window chrome needs,
// derived once per Encode call from opts. All of it traces back to the
// retired PNG renderer's own constants (image.go's initDefaults/SavePNG, at
// its factor = 2.0): margin 96, padding 48, titleOffset 80, corner radius
// 12, traffic-light radius 18 spaced 50 apart, a 2px window border, and a
// stackblur shadow of radius 32 offset (32, 32). Those numbers are what the
// PNG renderer drew at its own reference em size — a 48px FontSize, backed
// out from the reference renders' fixed 3648×632 canvas (120 columns ×
// ~28px advance + 2×96 margin + 2×48 padding = 3648) — so every one of them
// is scaled here by FontSize/48 to keep the same proportions at this
// package's actual FontSize (16px by default) instead of reproducing the
// PNG renderer's pixel values verbatim.
type windowGeometry struct {
	margin       float64
	padding      float64
	titleOffset  float64
	corner       float64
	trafficR     float64
	trafficGap   float64
	trafficNudge float64
	strokeWidth  float64
	shadowBlur   float64
	shadowOffset float64
}

func newWindowGeometry(opts *Options) windowGeometry {
	scale := opts.FontSize / 48.0

	return windowGeometry{
		margin:       96 * scale,
		padding:      48 * scale,
		titleOffset:  80 * scale,
		corner:       12 * scale,
		trafficR:     18 * scale,
		trafficGap:   50 * scale,
		trafficNudge: 4 * scale,
		strokeWidth:  2 * scale,
		shadowBlur:   32 * scale,
		shadowOffset: 32 * scale,
	}
}

// canvasSize is every box the window chrome and content grid need, computed
// once from a row count and geometry: the window itself (the rounded rect
// with the traffic lights and content inside it), the canvas as a whole
// (the window plus the margin the drop shadow needs room to fall into), and
// the content grid's own top-left corner inside the window.
type canvasSize struct {
	width, height             float64 // the full <svg> canvas, margin included
	windowX, windowY          float64
	windowWidth, windowHeight float64
	contentX, contentY        float64
}

func newCanvasSize(geo *windowGeometry, columns int, cellWidth float64, rows int, lineHeight float64) canvasSize {

package svg

import (
	"fmt"
	"strings"

	"github.com/jandedobbeleer/oh-my-posh/src/color"
)

// windowGeometry is every coordinate the terminal-window chrome needs,
// derived once per Encode call from opts. All of it traces back to the
// retired PNG renderer's own constants (image.go's initDefaults/SavePNG, at
// its factor = 2.0): margin 96, padding 48, titleOffset 80, corner radius
// 12, traffic-light radius 18 spaced 50 apart, a 2px window border, and a
// stackblur shadow of radius 32 offset (32, 32). Those numbers are what the
// PNG renderer drew at its own reference em size — a 48px FontSize, backed
// out from the reference renders' fixed 3648×632 canvas (120 columns ×
// ~28px advance + 2×96 margin + 2×48 padding = 3648) — so every one of them
// is scaled here by FontSize/48 to keep the same proportions at this
// package's actual FontSize (16px by default) instead of reproducing the
// PNG renderer's pixel values verbatim.
type windowGeometry struct {
	margin       float64
	padding      float64
	titleOffset  float64
	corner       float64
	trafficR     float64
	trafficGap   float64
	trafficNudge float64
	strokeWidth  float64
	shadowBlur   float64
	shadowOffset float64
}

func newWindowGeometry(opts *Options) windowGeometry {
	scale := opts.FontSize / 48.0

	return windowGeometry{
		margin:       96 * scale,
		padding:      48 * scale,
		titleOffset:  80 * scale,
		corner:       12 * scale,
		trafficR:     18 * scale,
		trafficGap:   50 * scale,
		trafficNudge: 4 * scale,
		strokeWidth:  2 * scale,
		shadowBlur:   32 * scale,
		shadowOffset: 32 * scale,
	}
}

// canvasSize is every box the window chrome and content grid need, computed
// once from a row count and geometry: the window itself (the rounded rect
// with the traffic lights and content inside it), the canvas as a whole
// (the window plus the margin the drop shadow needs room to fall into), and
// the content grid's own top-left corner inside the window.
type canvasSize struct {
	width, height             float64 // the full <svg> canvas, margin included
	windowX, windowY          float64
	windowWidth, windowHeight float64
	contentX, contentY        float64
}

func newCanvasSize(geo *windowGeometry, columns int, cellWidth float64, rows int, lineHeight float64) canvasSize {
	contentWidth := float64(columns) * cellWidth
	contentHeight := float64(rows) * lineHeight

	windowWidth := contentWidth + 2*geo.padding
	windowHeight := contentHeight + 2*geo.padding + geo.titleOffset

	return canvasSize{
		width:  windowWidth + 2*geo.margin,
		height: windowHeight + 2*geo.margin,

		windowX:      geo.margin,
		windowY:      geo.margin,
		windowWidth:  windowWidth,
		windowHeight: windowHeight,

		contentX: geo.margin + geo.padding,
		contentY: geo.margin + geo.padding + geo.titleOffset,
	}
}

// trafficLightColors are the three window-control dots, left to right, in
// the retired PNG renderer's own fixed colors (image.go's red/yellow/green
// constants) — never resolved against a theme, since a real terminal
// emulator's own window chrome isn't themed by the shell prompt running
// inside it either.
var trafficLightColors = [3]string{"#ED655A", "#E1C04C", "#71BD47"}

// writeWindowChrome draws the terminal window itself: a drop shadow (an
// SVG-native <feDropShadow> filter standing in for the retired PNG
// renderer's own stackblur pass — see windowGeometry's doc comment) cast by
// a single rounded <rect>, since feDropShadow derives the shadow's shape
// from that rect's own alpha silhouette and composites the crisp rect back
// on top, so one element does the job the old renderer needed a separate
// blurred rect underneath for. Three traffic-light <circle>s complete the
// impression of a window with controls, exactly matching the reference PNG
// renders' layout.
//
// fill is the window's own background: always opts.CanvasBackground, which
// withDefaults has already set to the real terminal background whenever
// that's known — see Options.CanvasBackground's doc comment on why a
// cutout glyph's color and the window's fill must always be the same
// value.
// Each element below is written via a single format string rather than
// interleaved WriteString calls — see writeRect's doc comment (svg.go) on
// why: this package renders once per prompt, so the allocation-averse style
// the interleaved calls used to be written in buys nothing here.
func writeWindowChrome(b *strings.Builder, size canvasSize, geo *windowGeometry, fill color.RGB) {
	const filterID = "omp-window-shadow"

	// #10101066 (the retired renderer's shadowBaseColor) split into its own
	// flood-color/flood-opacity: 0x66/255 ≈ 0.4, feDropShadow's dedicated
	// alpha channel, rather than relying on 8-digit #RRGGBBAA hex support.
	fmt.Fprintf(b, `<defs><filter id="%s" x="-50%%" y="-50%%" width="200%%" height="200%%">`+
		`<feDropShadow dx="%s" dy="%s" stdDeviation="%s" flood-color="#101010" flood-opacity="0.4"/></filter></defs>`+"\n",
		filterID, formatFloat(geo.shadowOffset), formatFloat(geo.shadowOffset), formatFloat(geo.shadowBlur))

	fmt.Fprintf(b, `<rect class="omp-window" x="%s" y="%s" width="%s" height="%s" rx="%s" fill="%s" `+
		`stroke="#404040" stroke-width="%s" filter="url(#%s)"/>`+"\n",
		formatFloat(size.windowX), formatFloat(size.windowY), formatFloat(size.windowWidth), formatFloat(size.windowHeight),
		formatFloat(geo.corner), hexString(fill), formatFloat(geo.strokeWidth), filterID)

	cy := size.windowY + geo.padding + geo.trafficNudge

	for i, hex := range trafficLightColors {
		cx := size.windowX + geo.padding + float64(i)*geo.trafficGap + geo.trafficNudge

		fmt.Fprintf(b, `<circle class="omp-traffic-light" cx="%s" cy="%s" r="%s" fill="%s"/>`+"\n",
			formatFloat(cx), formatFloat(cy), formatFloat(geo.trafficR), hex)
	}
}

