@font-face {
  font-family: "Victor Mono";
  src: url('/fonts/VictorMono.ttf') format("truetype");
  font-display: swap;
}

:root {
  --ifm-font-family-monospace: "Victor Mono", "Symbols Nerd Font Mono",
    "Symbols Nerd Font", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --ifm-font-family-base: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --ifm-heading-font-weight: 600;
  --ifm-heading-line-height: 1.2;
}

h1,
h2,
h3 {
  letter-spacing: -0.02em;
}

h1,
h2 {
  text-wrap: balance;
}

/* Page header parity: studio.js and segments.js each render a bare <h1>+<p> outside the
   .markdown wrapper that gives docs pages their 3rem heading (Infima's .markdown h1:first-child),
   so they were falling back to the plain 2rem h1 and reading as sub-pages of nothing next to the
   homepage hero (.hero__title, also 3rem). One definition, used by both pages, brings them in
   line; the breakpoint mirrors Infima's own docs breakpoint instead of inventing a new one. The
   intro paragraph is capped the same way the homepage subtitle is (52ch) - just wider, since these
   pages needed room for a plugin-computed count inline with prose - to stop it running the full
   ~1290px container at 150+ characters per line. */

