/* The product name as a wordmark rather than a sentence, so it is set in the font the prompt
   itself renders in (--ifm-font-family-monospace, "Victor Mono" - see custom.css) instead of the
   site's body face, and at 700 rather than the 600 every other heading uses. Ligatures off for
   the same reason code blocks turn them off: this face draws a script-like ligature across some
   letter pairs, which is charming in a terminal and wrong in a name. No max-width - it is three
   short words and never wraps mid-name at any width. */
.heroTitle {
  font-family: var(--ifm-font-family-monospace);
  font-weight: 700;
  font-variant-ligatures: none;
  font-feature-settings: "liga" 0, "calt" 0;
}

