142	
143		if files, OK := term.lsDirMap.Get(dir); OK {
144			dirEntries = files
145		}
146	
147		if len(dirEntries) == 0 {
148			var err error
149			dirEntries, err = fs.ReadDir(fileSystem, ".")
150			if err != nil {
151				log.Error(err)
152				log.Debug("false")
153				return false
154			}
155	
156			term.lsDirMap.Set(dir, dirEntries)
157		}
158	
159		pattern = strings.ToLower(pattern)
160	
161		for _, match := range dirEntries {
162			if match.IsDir() {
163				continue
164			}
165	
166			matchFileName, err := filepath.Match(pattern, strings.ToLower(match.Name()))
167			if err != nil {
168				log.Error(err)
169				log.Debug("false")
170				return false
171			}
172	
173			if matchFileName {
174				log.Debug("true")
