// candidate: stdlib unicode categories + x/text/width, no runewidth.
func candidate(r rune) int {
	if r < 0 || r > 0x10FFFF {
		return 0
	}

	// Control and format characters paint nothing.
	if r < 0x20 || (r >= 0x7F && r < 0xA0) {
		return 0
	}

	if unicode.In(r, unicode.Mn, unicode.Me, unicode.Cf) {
		return 0
	}

	switch width.LookupRune(r).Kind() {
	case width.EastAsianWide, width.EastAsianFullwidth:
		return 2
	}

	return 1
}

func main() {
	runewidth.DefaultCondition.EastAsianWidth = false

	diff := 0
	byDelta := map[string]int{}
	samples := []string{}

	for r := rune(0); r <= 0x10FFFF; r++ {
		want := runewidth.RuneWidth(r)
		got := candidate(r)
		if want == got {
			continue
		}
		diff++
		byDelta[fmt.Sprintf("%d->%d", want, got)]++
		if len(samples) < 10 {
			samples = append(samples, fmt.Sprintf("U+%04X %d->%d", r, want, got))
		}
	}

	fmt.Println("differing:", diff, "of 1114112")
	fmt.Println("by delta :", byDelta)
	fmt.Println("samples  :", samples)
}
