type run struct {
	lo, hi     rune
	want, got  int
	assigned   int
}

func main() {
	runewidth.DefaultCondition.EastAsianWidth = false

	var runs []run
	var cur *run

	for r := rune(0); r <= 0x10FFFF; r++ {
		want, got := runewidth.RuneWidth(r), candidate(r)
		if want == got {
			cur = nil
			continue
		}
		if cur != nil && cur.want == want && cur.got == got && cur.hi == r-1 {
			cur.hi = r
			if unicode.IsGraphic(r) {
				cur.assigned++
			}
			continue
		}
		runs = append(runs, run{lo: r, hi: r, want: want, got: got})
		cur = &runs[len(runs)-1]
		if unicode.IsGraphic(r) {
			cur.assigned++
		}
	}

	fmt.Printf("%d contiguous ranges\n\n", len(runs))
	fmt.Printf("%-22s %-8s %-6s %s\n", "range", "want->got", "count", "assigned(graphic)")
	for _, x := range runs {
