package config

import (
	"os"
	"strings"
	"testing"
)

func TestDumpTemplatesScratch(t *testing.T) {
	var b strings.Builder
	for segmentType, factory := range Segments {
		func() {
			defer func() { _ = recover() }()
			b.WriteString(string(segmentType))
			b.WriteString("\t")
			b.WriteString(strings.ReplaceAll(factory().Template(), "\n", " "))
			b.WriteString("\n")
		}()
	}
	_ = os.WriteFile("../../templates.scratch.txt", []byte(b.String()), 0o644)
}
EOF
