// Adds an explicit template to every bundled-theme segment that relies on its writer's default,
// copying that default verbatim so rendered output is unchanged (the goldens are the proof).
// Line-level insertion rather than a JSON round-trip: re-stringifying reformats 119 of the 124
// themes, which would bury an 18-line change in a 30,000-line diff.
import { readFileSync, writeFileSync, readdirSync } from 'node:fs';

const THEMES = 'D:/oh-my-posh/themes';
const GENERATED = 'D:/oh-my-posh/src/config/segment_templates_generated.go';

// Parse the generated table back into a map of segment type -> default template. Each line is
// `"type": "template",` with the template already Go-quoted, which is close enough to JSON that
// JSON.parse reads it correctly.
const defaults = new Map();
for (const line of readFileSync(GENERATED, 'utf8').split('\n')) {
  const m = line.match(/^\t("(?:[^"\\]|\\.)*"):\s+("(?:[^"\\]|\\.)*"),$/);
  if (m) defaults.set(JSON.parse(m[1]), JSON.parse(m[2]));
}

console.log(`defaults available: ${defaults.size}`);

let patchedFiles = 0;
let patchedSegments = 0;

for (const file of readdirSync(THEMES).filter((f) => f.endsWith('.omp.json'))) {
  const path = `${THEMES}/${file}`;
  const raw = readFileSync(path, 'utf8');
  const eol = raw.includes('\r\n') ? '\r\n' : '\n';
  const lines = raw.split(/\r?\n/);

  // Walk the file tracking brace depth so each segment object can be examined as a unit: find
  // where it opens and closes, then look for a "template" key between the two.
  const out = [];
  let changed = 0;

  for (let i = 0; i < lines.length; i++) {
    out.push(lines[i]);

    const typeMatch = lines[i].match(/^(\s*)"type":\s*"([^"]+)",?\s*$/);
    if (!typeMatch) continue;

    const [, indent, type] = typeMatch;

    // Find the enclosing object's extent by walking back to its `{` and forward to its `}`.
    let depth = 0;
    let start = i;
    for (; start >= 0; start--) {
      for (const ch of [...lines[start]].reverse()) {
        if (ch === '}') depth++;
        if (ch === '{') { if (depth === 0) { depth = -1; break; } depth--; }
      }
      if (depth === -1) break;
    }

    depth = 0;
    let end = start;
    for (; end < lines.length; end++) {
      for (const ch of lines[end]) {
        if (ch === '{') depth++;
        if (ch === '}') { depth--; if (depth === 0) break; }
      }
      if (depth === 0 && end > start) break;
    }

    const body = lines.slice(start, end + 1).join('\n');
    if (/^\s*"template":/m.test(body)) continue;

    const fallback = defaults.get(type);
    if (fallback === undefined) {
      console.warn(`  ${file}: ${type} has no default, skipped`);
      continue;
    }

    out.push(`${indent}"template": ${JSON.stringify(fallback)},`);
    changed++;
  }

  if (!changed) continue;

  writeFileSync(path, out.join(eol));
  patchedFiles++;
  patchedSegments += changed;
  console.log(`  ${file.padEnd(28)} +${changed}`);
}

console.log(`\npatched ${patchedSegments} segments across ${patchedFiles} themes`);

