// Adds an explicit template to every bundled-theme segment that relies on its writer's default,
// copying that default verbatim so rendered output is unchanged (the goldens are the proof).
//
// Line-level insertion rather than a JSON round-trip: re-stringifying reformats 119 of the 124
// themes, which would bury an 18-line change in a 30,000-line diff.
//
// The defaults come from a JSON dump of the live registry rather than from parsing the Go source:
// three of them contain astral glyphs (claude U+F0BC9, nba U+F0806, ramadan U+1F319) written as
// Go's 8-digit \U escapes, which are not valid JSON and need surrogate pairs in JS. Round-tripping
// through Go's own json.Marshal keeps them intact without any hand-rolled unquoting.
import { readFileSync, writeFileSync, readdirSync } from 'node:fs';

const THEMES = 'D:/oh-my-posh/themes';
const DEFAULTS = process.argv[2];

const defaults = new Map(Object.entries(JSON.parse(readFileSync(DEFAULTS, 'utf8'))));
console.log(`defaults available: ${defaults.size}`);

// Returns the [start, end] line range of the object enclosing line i.
function enclosingObject(lines, i) {
  let depth = 0;
  let start = i;

  for (; start >= 0; start--) {
    const chars = [...lines[start]].reverse();
    let found = false;

    for (const ch of chars) {
      if (ch === '}') depth++;
      else if (ch === '{') {
        if (depth === 0) { found = true; break; }
        depth--;
      }
    }

    if (found) break;
  }

  depth = 0;
  let end = start;

  for (; end < lines.length; end++) {
    let closed = false;

    for (const ch of lines[end]) {
      if (ch === '{') depth++;
      else if (ch === '}') {
        depth--;
        if (depth === 0) { closed = true; break; }
      }
    }

    if (closed) break;
  }

  return [start, end];
}

let patchedFiles = 0;
let patchedSegments = 0;

for (const file of readdirSync(THEMES).filter((f) => f.endsWith('.omp.json'))) {
  const path = `${THEMES}/${file}`;
  const raw = readFileSync(path, 'utf8');
  const eol = raw.includes('\r\n') ? '\r\n' : '\n';
  const lines = raw.split(/\r?\n/);

  const out = [];
  let changed = 0;

  for (let i = 0; i < lines.length; i++) {
    const typeMatch = lines[i].match(/^(\s*)"type":\s*"([^"]+)",?\s*$/);

    if (!typeMatch) {
      out.push(lines[i]);
      continue;
    }

    const [, indent, type] = typeMatch;
    const [start, end] = enclosingObject(lines, i);
    const body = lines.slice(start, end + 1).join('\n');
    const fallback = defaults.get(type);

    // Block objects also carry a "type" (prompt/rprompt) and have no default; so do segments that
    // already spell their template out.
    if (fallback === undefined || /^\s*"template":/m.test(body)) {
      out.push(lines[i]);
      continue;
    }

    // Before the "type" line, never after: "type" is sometimes the object's last property and so
    // carries no trailing comma, and appending after it would leave the pair uncommaed.
    out.push(`${indent}"template": ${JSON.stringify(fallback)},`);
    out.push(lines[i]);
    changed++;
  }

  if (!changed) continue;

  writeFileSync(path, out.join(eol));
  patchedFiles++;
  patchedSegments += changed;
  console.log(`  ${file.padEnd(28)} +${changed}`);
}

console.log(`\npatched ${patchedSegments} segments across ${patchedFiles} themes`);

