	if headless {
		return installHeadless(font, zipFolder)
	}

	return tui(font, zipFolder)
}

func tui(font, zipFolder string) (string, error) {
	main := &main{
		Asset: Asset{
			Name:   font,
			URL:    font,
			Folder: zipFolder,
		},
	}

	program = tea.NewProgram(main)
	_, err := program.Run()
	return main.Name, err
}

